#!/usr/bin/env node
// Kit-managed. Generated by design4pro/agent-kit - edit the template there, never this copy.
// This file is listed in .ai/agent-kit.lock.json and hashes itself, so an edit here is caught by
// the next run of this very script.
//
// It answers exactly one question, offline, with no dependencies and no network: has anyone
// hand-edited a file the kit generated? It re-hashes every path recorded in the lock.
//
// It deliberately cannot answer "is this repository behind the kit?". That question needs the kit,
// and this repository's CI never fetches it: the gate must hold with no token beyond its own and no
// network. "Behind the kit" is answered from the kit's side - its sync-consumers workflow renders
// the kit into this repository and opens an ordinary pull request, which a human merges.
//
// With `--base <ref>` it answers one more, and this one it can: is this branch behind the base's
// pipeline layer? That needs no network either - the answer is in the base commit's own lock, and
// `kitVersion` is the only orderable thing a consumer repository has. It matters because a
// `pr-autopilot` or `pr-fix` run checks out the PR head and therefore runs whatever agent layer
// that branch carries. A branch cut before a pipeline change runs the old hooks, the old
// workflows and the old guards, and nothing else notices.
//
// `--head <ref>` names the tree that comparison is about, and CI must pass it. On a pull_request
// event actions/checkout hands the job refs/pull/N/merge, and a three-way merge takes the base's
// side of the lock whenever the head never touched it - which is exactly what a stale branch looks
// like. Judging the worktree there compares the base against itself and passes every stale branch:
// the gate would exist and never fire. The hash half stays on the worktree, where it belongs - a
// hand edit should be caught in the state that would land.
//
// It lives under .ai/scripts/ rather than scripts/ because guard-generated.sh already refuses
// edits under .ai/scripts/ whenever CEZ_TASK_ID or GITHUB_ACTIONS is set. A cezar run therefore
// cannot rewrite the checker that judges it, which a top-level scripts/ path would have allowed.
//
// Exit codes, because callers distinguish them:
//   0  clean
//   1  a managed file was hand-edited, or a hook lost its executable bit
//   2  a managed file is missing, or the lock is absent or malformed
//   3  --base only: this branch's pipeline layer is older than the base branch's

import { readFileSync, existsSync, statSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const LOCK_PATH = join(ROOT, ".ai/agent-kit.lock.json");

// Both `--base <ref>` and `--base=<ref>`, and nothing else. An argument this script does not
// understand is not ignored: `--base=origin/develop` under an indexOf-only parser left BASE null,
// skipped the staleness half entirely and exited 0 - the same silent non-gating the script exists
// to prevent, one level up. A typo must be as red as a real failure.
const ARGV = process.argv.slice(2);
const consumed = new Set();

function refArg(flag, example) {
  const bad = () => {
    console.error(`agent-kit: ${flag} needs a git ref, e.g. ${flag} ${example}`);
    process.exit(2);
  };
  const eqAt = ARGV.findIndex((a) => a.startsWith(`${flag}=`));
  if (eqAt !== -1) {
    consumed.add(eqAt);
    const value = ARGV[eqAt].slice(flag.length + 1);
    if (!value) bad();
    return value;
  }
  const at = ARGV.indexOf(flag);
  if (at === -1) return null;
  consumed.add(at);
  // A value starting with `-` is a swallowed flag, not a ref: `--base --head x` would otherwise
  // set BASE to "--head" and report it as an unresolvable ref, naming the wrong mistake.
  const value = ARGV[at + 1];
  if (!value || value.startsWith("-")) bad();
  consumed.add(at + 1);
  return value;
}

const BASE = refArg("--base", "origin/develop");
const HEAD = refArg("--head", "origin/pr-head");

const stray = ARGV.filter((_, i) => !consumed.has(i));
if (stray.length) {
  console.error(`agent-kit: unrecognised argument(s): ${stray.join(" ")}`);
  console.error("agent-kit: usage: agent-kit-check.mjs [--base <ref> [--head <ref>]]");
  process.exit(2);
}
if (HEAD && !BASE) {
  console.error("agent-kit: --head says which tree to judge; it needs --base to judge it against.");
  process.exit(2);
}

// The remedy is a host action, and saying so is most of this script's value: a cezar run that hits
// this cannot fix it - guard-generated.sh blocks the very paths involved - so the message has to
// end the run as a clean blocked handoff instead of sending it round a loop it cannot exit.
const REMEDY = [
  "",
  "These files are generated by design4pro/agent-kit. To resolve, on the host:",
  "  node ../agent-kit/bin/sync.mjs --repo .    and commit the result,",
  "or move your change into the kit's template so both repositories get it.",
  "Do not hand-edit them here. An agent run cannot fix this and should stop.",
].join("\n");

// Staleness has a different fix, and offering the sync here would be wrong twice over: it would
// send a developer to rewrite files that are already correct, and a cezar run cannot run the sync
// at all.
const MERGE_REMEDY = [
  "",
  "Merge the base branch before an agent run touches this one:",
  "  git merge origin/<base>    and push.",
  "A pr-autopilot or pr-fix run checks out this head, so until then it would run",
  "the older hooks, workflows and guards this branch still carries.",
].join("\n");

// A malformed --base argument is a workflow bug, not a hand edit, so those calls pass no remedy
// rather than pointing a developer at a sync that would not help.
function die(code, lines, remedy = REMEDY) {
  for (const l of lines) console.error(l);
  if (remedy) console.error(remedy);
  process.exit(code);
}

if (!existsSync(LOCK_PATH)) {
  die(2, ["agent-kit: .ai/agent-kit.lock.json is missing."]);
}

let lock;
try {
  lock = JSON.parse(readFileSync(LOCK_PATH, "utf8"));
} catch (e) {
  die(2, [
    `agent-kit: .ai/agent-kit.lock.json is not valid JSON - ${e.message}`,
  ]);
}
if (!lock || typeof lock !== "object" || !lock.rendered) {
  die(2, ["agent-kit: .ai/agent-kit.lock.json has no `rendered` section."]);
}

const sha256 = (buf) => createHash("sha256").update(buf).digest("hex");

const missing = [];
const edited = [];
const disarmed = [];

// `rendered` is what the kit writes; `watched` is what it only pins. skills-lock.json is the
// second kind: `pnpm install-skills` owns that file, but it installs upstream HEAD, so an
// unexplained move of it is exactly the silent failure worth a red gate. Pinning the hash makes a
// skills upgrade a deliberate act that updates the lock in the same pull request.
for (const [section, entries] of [
  ["rendered", lock.rendered],
  ["watched", lock.watched || {}],
]) {
  for (const [rel, want] of Object.entries(entries)) {
    const abs = join(ROOT, rel);
    if (!existsSync(abs)) {
      missing.push(`${rel}  (${section})`);
      continue;
    }
    if (sha256(readFileSync(abs)) !== want.sha256) edited.push(rel);

    // Only the executable bit, never the full mode: git records 100644 or 100755 and nothing else,
    // so comparing all nine permission bits would fail on a different umask while proving nothing.
    // The bit itself matters - Claude Code treats an unrunnable hook as no hook, in silence.
    if (want.mode) {
      const isExec = (statSync(abs).mode & 0o111) !== 0;
      if (isExec !== want.mode.endsWith("755"))
        disarmed.push(`${rel}  (want ${want.mode})`);
    }
  }
}

if (missing.length) {
  die(2, [
    `agent-kit: ${missing.length} managed file(s) missing:`,
    ...missing.map((m) => `  ${m}`),
  ]);
}
if (edited.length || disarmed.length) {
  const lines = [];
  if (edited.length) {
    lines.push(`agent-kit: ${edited.length} managed file(s) hand-edited:`);
    lines.push(...edited.map((m) => `  ${m}`));
  }
  if (disarmed.length) {
    lines.push(
      `agent-kit: ${disarmed.length} file(s) with the wrong executable bit:`,
    );
    lines.push(...disarmed.map((m) => `  ${m}`));
  }
  die(1, lines);
}

const n =
  Object.keys(lock.rendered).length + Object.keys(lock.watched || {}).length;
console.log(
  `agent-kit: ${n} managed files match the lock (kit version ${lock.kitVersion}).`,
);

if (!BASE) process.exit(0);

// Both sides are read out of git rather than the worktree: what matters is what each commit
// carries. Returns null when the ref resolves but carries no lock - a real and different answer
// from "that ref does not exist", and the two must not collapse into one.
function kitVersionAt(ref) {
  let text;
  try {
    text = execFileSync(
      "git",
      ["-C", ROOT, "show", `${ref}:.ai/agent-kit.lock.json`],
      { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] },
    );
  } catch {
    // A ref that cannot be resolved at all is a misconfigured workflow, and passing there is how a
    // gate quietly stops gating.
    try {
      execFileSync("git", ["-C", ROOT, "rev-parse", "--verify", `${ref}^{commit}`], {
        stdio: "ignore",
      });
    } catch {
      die(
        2,
        [
          `agent-kit: ${ref} does not resolve to a commit.`,
          "  In CI this usually means the ref was never fetched:",
          '  git fetch --depth=1 origin "$BASE"  before running this.',
        ],
        "",
      );
    }
    return null;
  }
  try {
    return JSON.parse(text).kitVersion;
  } catch (e) {
    die(2, [`agent-kit: the lock at ${ref} is not valid JSON - ${e.message}`], "");
  }
}

const baseVersion = kitVersionAt(BASE);
if (baseVersion === null) {
  // Ordinary history - it was true of both repositories until the kit landed - so there is nothing
  // to be behind, and the gate passes loudly rather than in silence.
  console.log(
    `agent-kit: ${BASE} carries no lock, so there is no pipeline layer to be behind.`,
  );
  process.exit(0);
}

const WHERE = HEAD ? `${HEAD}` : "this worktree";
const branchVersion = HEAD ? kitVersionAt(HEAD) : lock.kitVersion;

// The base is managed and this head is not: a branch cut before the repository adopted the kit at
// all. That is as behind as a branch gets, and the same merge fixes it.
if (branchVersion === null) {
  die(
    3,
    [
      `agent-kit: ${WHERE} carries no lock, and ${BASE} is at kit version ${baseVersion}.`,
      "  This branch predates the agent-kit adoption.",
    ],
    MERGE_REMEDY,
  );
}

if (typeof baseVersion !== "number" || typeof branchVersion !== "number") {
  die(
    2,
    [
      "agent-kit: kitVersion is not a number on one side, so the two cannot be ordered.",
      `  ${WHERE}: ${JSON.stringify(branchVersion)}`,
      `  ${BASE}: ${JSON.stringify(baseVersion)}`,
    ],
    "",
  );
}

// Ahead is fine and is what a sync pull request looks like. Only behind is a problem.
if (branchVersion < baseVersion) {
  die(
    3,
    [
      `agent-kit: this branch's pipeline layer is older than ${BASE}'s.`,
      `  ${WHERE}: kit version ${branchVersion}`,
      `  ${BASE}: kit version ${baseVersion}`,
    ],
    MERGE_REMEDY,
  );
}

console.log(
  `agent-kit: not behind ${BASE} (${WHERE} at kit version ${branchVersion} against ${baseVersion}).`,
);
